package com.gathin.tvhome;
import java.net.*;import java.io.*;import org.json.*;
final class WeatherSearch{
 static JSONArray search(String name)throws Exception{if(name.trim().length()<2||name.length()>60)throw new IllegalArgumentException("请输入至少两个字的城市名称");HttpURLConnection c=(HttpURLConnection)new URL("https://geocoding-api.open-meteo.com/v1/search?count=10&language=zh&format=json&name="+android.net.Uri.encode(name.trim())).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);try{if(c.getResponseCode()!=200)throw new IOException("城市搜索服务暂不可用");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("搜索结果过大");out.write(b,0,n);}}JSONArray source=new JSONObject(out.toString("UTF-8")).optJSONArray("results"),result=new JSONArray();if(source!=null)for(int i=0;i<source.length();i++){JSONObject x=source.getJSONObject(i);result.put(new JSONObject().put("city",x.getString("name")).put("label",x.getString("name")+" · "+x.optString("admin1")+" · "+x.optString("country")).put("latitude",String.valueOf(x.getDouble("latitude"))).put("longitude",String.valueOf(x.getDouble("longitude"))).put("timezone",x.optString("timezone","Asia/Shanghai")));}return result;}finally{c.disconnect();}}
}
